import React, { useState } from 'react';

type ValidationResult = {
  title: string;
  regexName: string;
  passed: boolean;
  tags: string[];
};

type InputFormProps = {
  inputTitle: string;
  onInputChange: (title: string) => void;
  onValidate: (results: ValidationResult[]) => void;
  regexDefinitions: { name: string; pattern: string; tags: string[] }[];
};

const InputForm: React.FC<InputFormProps> = ({
  inputTitle,
  onInputChange,
  onValidate,
  regexDefinitions,
}) => {
  const [inputValue, setInputValue] = useState(inputTitle);

  const handleInputChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = event.target.value;
    setInputValue(value);
    onInputChange(value);
  };

  const validateInput = () => {
    const results = regexDefinitions.map((regexDef) => {
      let passed = false;
      try {
        const regex = new RegExp(regexDef.pattern, 'i');
        passed = regex.test(inputValue);
      } catch {
        passed = false;
      }
      return {
        title: inputValue,
        regexName: regexDef.name,
        passed,
        tags: passed ? regexDef.tags : [],
      };
    });
    onValidate(results);
  };

  return (
    <div className="input-form">
      <textarea
        value={inputValue}
        onChange={handleInputChange}
        placeholder="Enter title text"
        maxLength={200}
        rows={4}
      />
      <button type="button" onClick={validateInput} disabled={inputValue.length < 5}>
        Validate
      </button>
    </div>
  );
};

export default InputForm;
